let balance = 0;
for (let order = 1; order <= 10; order++) {
  balance += 0.1; // 0.10 EGP cashback per order
}

console.log(balance); // 0.9999999999999999
console.log(balance >= 1); // false: "Redeem 1 EGP" stays disabled
console.log(balance.toFixed(2)); // 1.00, but it's a string
console.log((0.1).toFixed(2) + (0.2).toFixed(2)); // 0.100.20
console.log((2.55).toFixed(1)); // 2.5: 2.55 is stored slightly below

let balance = 0; // in piastres: 1 EGP = 100 piastres
for (let order = 1; order <= 10; order++) {
  balance += 10; // integers add exactly
}

console.log(balance >= 100); // true
const egp = new Intl.NumberFormat("en-EG", {
  style: "currency",
  currency: "EGP",
});
console.log(egp.format(balance / 100)); // EGP 1.00
